/**
 * Natural German speech generated by the server (OpenAI text-to-speech, see the tts
 * function). Each text is generated once for everyone and then served as a stored MP3,
 * so a second play costs nothing. Anything that goes wrong — offline, no credit, the
 * function not installed yet — makes the player fall back to the phone's own voice.
 */
import type { AudioProvider, SpeakRequest } from './audio.ts'

export interface CloudSpeechDeps {
  /** Calls the tts function; resolves to the public URL of the MP3. */
  fetchUrl(text: string, voice: 'female' | 'male'): Promise<string>
  enabled(): boolean
  voice(): 'female' | 'male'
  online(): boolean
  storage?: Pick<Storage, 'getItem' | 'setItem'>
}

const URLS_KEY = 'hodhod.tts.urls'
const MAX_REMEMBERED = 600
/** How long a learner waits for a fresh recording before the phone's voice takes over. */
const FETCH_TIMEOUT_MS = 7_000
/** A tiny silent MP3, played on the first touch so iOS allows later playback. */
const SILENCE = 'data:audio/mpeg;base64,'

function key(text: string, voice: string): string {
  return `${voice}|${text.trim()}`
}

export class CloudSpeechProvider implements AudioProvider {
  readonly id = 'cloud-speech'
  private readonly audio: HTMLAudioElement | null
  private urls = new Map<string, string>()
  /** Set when the server says speech is not available at all (not installed / not configured). */
  private disabled = false
  private stopRequested: (() => void) | null = null

  constructor(private readonly deps: CloudSpeechDeps) {
    this.audio = typeof Audio !== 'undefined' ? new Audio() : null
    if (this.audio) this.audio.preload = 'auto'
    try {
      const saved = JSON.parse(deps.storage?.getItem(URLS_KEY) ?? '[]') as [string, string][]
      this.urls = new Map(saved.slice(-MAX_REMEMBERED))
    } catch {
      this.urls = new Map()
    }
    this.unlockOnFirstTouch()
  }

  /** iOS only lets a page play sound it started from a touch; one silent play unlocks the element. */
  private unlockOnFirstTouch(): void {
    if (!this.audio || typeof document === 'undefined') return
    const unlock = () => {
      document.removeEventListener('touchend', unlock, true)
      document.removeEventListener('click', unlock, true)
      const a = this.audio!
      if (!a.paused || a.src) return
      a.src = SILENCE
      a.play().then(() => a.pause(), () => undefined)
    }
    document.addEventListener('touchend', unlock, true)
    document.addEventListener('click', unlock, true)
  }

  canSpeak(lang: string): boolean {
    return !this.disabled && this.audio !== null && lang.toLowerCase().startsWith('de') && this.deps.enabled() && this.deps.online()
  }

  private remember(k: string, url: string): void {
    this.urls.delete(k)
    this.urls.set(k, url)
    while (this.urls.size > MAX_REMEMBERED) this.urls.delete(this.urls.keys().next().value!)
    try {
      this.deps.storage?.setItem(URLS_KEY, JSON.stringify([...this.urls]))
    } catch {
      // storage full or blocked: the server cache still answers quickly
    }
  }

  /** The MP3 address for a text, asking the server only the first time. */
  async urlFor(text: string): Promise<string> {
    const voice = this.deps.voice()
    const k = key(text, voice)
    const known = this.urls.get(k)
    if (known) return known
    let timer: ReturnType<typeof setTimeout> | undefined
    try {
      const url = await Promise.race([
        this.deps.fetchUrl(text.trim(), voice),
        new Promise<never>((_, reject) => (timer = setTimeout(() => reject(new Error('tts timeout')), FETCH_TIMEOUT_MS))),
      ])
      this.remember(k, url)
      return url
    } catch (err) {
      const code = (err as { code?: string; kind?: string }).code ?? ''
      // not installed (404) or not configured: stop asking for the rest of the session
      if (code === 'not_found' || code === 'not_configured' || (err as { kind?: string }).kind === 'not_found') this.disabled = true
      throw err
    } finally {
      clearTimeout(timer)
    }
  }

  /** Fetches the recording ahead of time (e.g. while the card is on screen). */
  prefetch(text: string): void {
    if (!this.canSpeak('de')) return
    void this.urlFor(text).catch(() => undefined)
  }

  async speak({ text, rate }: SpeakRequest): Promise<void> {
    const audio = this.audio
    if (!audio) throw new Error('no audio element')
    let cancelled = false
    this.stopRequested = () => (cancelled = true)
    const url = await this.urlFor(text)
    if (cancelled) return
    audio.src = url
    audio.playbackRate = Math.max(0.5, Math.min(2, rate))
    ;(audio as HTMLAudioElement & { preservesPitch?: boolean }).preservesPitch = true
    await new Promise<void>((resolve, reject) => {
      const done = () => {
        cleanup()
        resolve()
      }
      const fail = () => {
        cleanup()
        reject(new Error('audio playback failed'))
      }
      const cleanup = () => {
        audio.removeEventListener('ended', done)
        audio.removeEventListener('pause', done)
        audio.removeEventListener('error', fail)
      }
      audio.addEventListener('ended', done)
      audio.addEventListener('error', fail)
      audio.play().then(() => audio.addEventListener('pause', done), fail)
    })
  }

  stop(): void {
    this.stopRequested?.()
    this.stopRequested = null
    if (this.audio && !this.audio.paused) this.audio.pause()
  }
}
